PRAGMA page_size=4096;
PRAGMA encoding='UTF-8';
PRAGMA auto_vacuum=NONE;
PRAGMA journal_mode=MEMORY;
PRAGMA synchronous=FULL;
PRAGMA temp_store=MEMORY;
PRAGMA foreign_keys=ON;
PRAGMA trusted_schema=OFF;
PRAGMA application_id=1162102577;
PRAGMA user_version=1;
CREATE TABLE projection_policy(singleton INTEGER PRIMARY KEY CHECK(singleton=1),projection_schema TEXT NOT NULL CHECK(projection_schema='ergentics_disposal_graph_v1'),authority_vector TEXT NOT NULL CHECK(authority_vector='00000000'),authoritative INTEGER NOT NULL CHECK(authoritative=0),may_feed_controller INTEGER NOT NULL CHECK(may_feed_controller=0),prose_may_supply_fact INTEGER NOT NULL CHECK(prose_may_supply_fact=0),unavailable_behavior TEXT NOT NULL CHECK(unavailable_behavior='EMPTY_OR_EXPLICIT_ABSTAIN_NO_STALE_FALLBACK')) STRICT;
CREATE TABLE input_databases(database_role TEXT PRIMARY KEY CHECK(database_role IN('EVIDENCE','METRICS')),projection_id TEXT NOT NULL CHECK(length(projection_id)=64),database_sha256 TEXT NOT NULL UNIQUE CHECK(length(database_sha256)=64),database_bytes INTEGER NOT NULL CHECK(database_bytes>0),relational_export_sha256 TEXT NOT NULL CHECK(length(relational_export_sha256)=64)) STRICT,WITHOUT ROWID;
CREATE TABLE graph_nodes(node_id TEXT PRIMARY KEY CHECK(length(node_id)=64),node_kind TEXT NOT NULL CHECK(node_kind IN('INVOCATION','STREAM','FRAME','ADAPTER_COVERAGE','TARGET','RECEIPT','VNODE_JOIN','DOMAIN_SNAPSHOT','SNAPSHOT','SNAPSHOT_PAIR','COMMITMENT','SIGNAL_CALL','SIGNAL_ZERO_CALL','WAIT','REAP','ABSENCE_PROOF','ABSENCE_ATTEMPT','CONSERVATION','CONSERVATION_SET_COMMITMENT','CONSERVATION_SET_MEMBERSHIP','MERKLE_PROOF_NODE','CONSERVATION_SET_STATE','CONSERVATION_SET_MAPPING','NAMESPACE_OBSERVATION','MISSING_EVIDENCE','TERMINAL_OUTCOME','RUSAGE_SAMPLE','METRIC','RISK_WINDOW','DIGEST')),canonical_key TEXT NOT NULL UNIQUE,display_label TEXT NOT NULL,source_database_role TEXT NOT NULL REFERENCES input_databases(database_role),source_row_id TEXT NOT NULL,authoritative INTEGER NOT NULL CHECK(authoritative=0)) STRICT,WITHOUT ROWID;
CREATE TABLE graph_edges(edge_id TEXT PRIMARY KEY CHECK(length(edge_id)=64),from_node_id TEXT NOT NULL REFERENCES graph_nodes(node_id),predicate TEXT NOT NULL CHECK(predicate IN('STREAM_CONTAINS_FRAME','FRAME_PRECEDES_FRAME','FRAME_REPORTS_ENTITY','INVOCATION_HAS_TARGET','ENTITY_REFERENCES_TARGET','VNODE_JOIN_USES_RECEIPT','SNAPSHOT_DESCRIBES_TARGET','SNAPSHOT_USES_RECEIPT','SNAPSHOT_USES_VNODE_JOIN','SNAPSHOT_USES_DOMAIN_SNAPSHOT','DOMAIN_CONTAINS_RECEIPT','PAIR_REFERENCES_FIRST','PAIR_REFERENCES_SECOND','COMMITMENT_REFERENCES_PAIR','CALL_REFERENCES_COMMITMENT','CALL_REFERENCES_PAIR','WAIT_RETURNED_REAP_RECEIPT','ABSENCE_PROOF_USES_ATTEMPT','ABSENCE_PROOF_ACCEPTS_ATTEMPT','ATTEMPT_USES_SIGNAL_ZERO','ATTEMPT_USES_DOMAIN_SNAPSHOT','CONSERVATION_USES_ABSENCE_PROOF','CONSERVATION_REFERENCES_REAP','TERMINAL_REFERENCES_CONSERVATION','SET_CONTAINS_MEMBERSHIP','MEMBERSHIP_REFERENCES_COMMITMENT','MEMBERSHIP_HAS_PROOF_NODE','CONSERVATION_HAS_SET_STATE','SET_STATE_REFERENCES_SET','SET_MAPPING_REFERENCES_CONSERVATION','SET_MAPPING_REFERENCES_SET','SET_MAPPING_REFERENCES_MEMBERSHIP','METRIC_USES_SAMPLE','WINDOW_SPANS_EVENTS','WINDOW_REFERENCES_COMMITMENT','WINDOW_REFERENCES_SIGNAL_CALL','INVOCATION_REPORTS_MISSING_EVIDENCE','ENTITY_HASHES_TO','ENTITY_MENTIONS_DIGEST')),to_node_id TEXT NOT NULL REFERENCES graph_nodes(node_id),source_database_role TEXT NOT NULL REFERENCES input_databases(database_role),source_row_id TEXT NOT NULL,source_pointer TEXT,evidence_grade TEXT NOT NULL CHECK(evidence_grade IN('FOREIGN_KEY_EXACT','SOURCE_POINTER_EXACT','COMPUTED_SHA256_EXACT','LEXICAL_EQUALITY_ONLY','OFFLINE_RATIONAL_EXACT_UNDER_PINNED_PREMISES')),authoritative INTEGER NOT NULL CHECK(authoritative=0),may_feed_controller INTEGER NOT NULL CHECK(may_feed_controller=0)) STRICT,WITHOUT ROWID;
CREATE TABLE state_evaluations(evaluation_id TEXT PRIMARY KEY CHECK(length(evaluation_id)=64),invocation_node_id TEXT NOT NULL REFERENCES graph_nodes(node_id),rule_id TEXT NOT NULL,ruleset_sha256 TEXT NOT NULL CHECK(length(ruleset_sha256)=64),high_water_node_id TEXT REFERENCES graph_nodes(node_id),state_class TEXT NOT NULL CHECK(state_class IN('EMPTY','ABSTAIN_INCOMPLETE','PREFLIGHT_ONLY','COMMITMENT_RECORDED_MAY_HAVE_ENTERED','CONTAINMENT_REQUIRED','CONSERVATION_RECORDED','TERMINAL_RECORDED','REJECTED')),authority_vector TEXT NOT NULL CHECK(authority_vector='00000000'),authoritative INTEGER NOT NULL CHECK(authoritative=0),may_feed_controller INTEGER NOT NULL CHECK(may_feed_controller=0),UNIQUE(invocation_node_id,ruleset_sha256)) STRICT,WITHOUT ROWID;
CREATE TABLE state_inputs(evaluation_id TEXT NOT NULL REFERENCES state_evaluations(evaluation_id),input_ordinal INTEGER NOT NULL CHECK(input_ordinal>=0),input_node_id TEXT NOT NULL REFERENCES graph_nodes(node_id),input_row_sha256 TEXT NOT NULL CHECK(length(input_row_sha256)=64),PRIMARY KEY(evaluation_id,input_ordinal),UNIQUE(evaluation_id,input_node_id)) STRICT,WITHOUT ROWID;
CREATE TABLE machine_nodes(machine_node_id TEXT PRIMARY KEY CHECK(length(machine_node_id)=64),partition_kind TEXT NOT NULL CHECK(partition_kind IN('OBJECT','RELATION')),machine_kind TEXT NOT NULL CHECK(machine_kind IN('STATE','WITNESS','TRANSITION')),authoritative INTEGER NOT NULL CHECK(authoritative=0),may_feed_controller INTEGER NOT NULL CHECK(may_feed_controller=0),CHECK((partition_kind='OBJECT' AND machine_kind IN('STATE','WITNESS')) OR (partition_kind='RELATION' AND machine_kind='TRANSITION'))) STRICT,WITHOUT ROWID;
CREATE TABLE machine_states(state_id TEXT PRIMARY KEY REFERENCES machine_nodes(machine_node_id),prefix_ordinal INTEGER NOT NULL UNIQUE CHECK(prefix_ordinal>=-1),predecessor_state_id TEXT REFERENCES machine_states(state_id),ancestry_sha256 TEXT NOT NULL CHECK(length(ancestry_sha256)=64),high_water_frame_lf_sha256 TEXT CHECK(high_water_frame_lf_sha256 IS NULL OR length(high_water_frame_lf_sha256)=64),matched_rule_id TEXT NOT NULL CHECK(matched_rule_id IN('D00','D10','D20','D30','D50','D60','D70','D80')),predicate_vector_sha256 TEXT NOT NULL CHECK(length(predicate_vector_sha256)=64),state_class TEXT NOT NULL CHECK(state_class IN('EMPTY','ABSTAIN_INCOMPLETE','PREFLIGHT_ONLY','COMMITMENT_RECORDED_MAY_HAVE_ENTERED','CONTAINMENT_REQUIRED','CONSERVATION_RECORDED','TERMINAL_RECORDED','REJECTED')),derived_post_hoc_witness_merkle_root_sha256 TEXT NOT NULL CHECK(length(derived_post_hoc_witness_merkle_root_sha256)=64),derived_post_hoc_witness_leaf_count INTEGER NOT NULL CHECK(derived_post_hoc_witness_leaf_count>=0),merkle_algorithm TEXT NOT NULL CHECK(merkle_algorithm='SHA256'),merkle_domain_tag TEXT NOT NULL CHECK(merkle_domain_tag='ERGENTICS_DISPOSAL_DERIVED_POST_HOC_WITNESS_PREFIX_V1'),merkle_leaf_ordering TEXT NOT NULL CHECK(merkle_leaf_ordering='CANONICAL_LEAF_KEY_BYTES_ASC'),merkle_duplicate_policy TEXT NOT NULL CHECK(merkle_duplicate_policy='REJECT_DUPLICATES'),merkle_odd_leaf_rule TEXT NOT NULL CHECK(merkle_odd_leaf_rule='RFC6962_LARGEST_POWER_OF_TWO_SPLIT'),authority_vector TEXT NOT NULL CHECK(authority_vector='00000000'),authoritative INTEGER NOT NULL CHECK(authoritative=0),may_feed_controller INTEGER NOT NULL CHECK(may_feed_controller=0),CHECK((prefix_ordinal=-1 AND predecessor_state_id IS NULL AND high_water_frame_lf_sha256 IS NULL AND matched_rule_id='D00' AND state_class='EMPTY') OR (prefix_ordinal>=0 AND predecessor_state_id IS NOT NULL AND high_water_frame_lf_sha256 IS NOT NULL))) STRICT,WITHOUT ROWID;
CREATE TABLE machine_state_bindings(state_id TEXT PRIMARY KEY REFERENCES machine_states(state_id),invocation_node_id TEXT NOT NULL REFERENCES graph_nodes(node_id),high_water_frame_node_id TEXT REFERENCES graph_nodes(node_id)) STRICT,WITHOUT ROWID;
CREATE TABLE machine_transitions(transition_id TEXT PRIMARY KEY REFERENCES machine_nodes(machine_node_id),from_state_id TEXT NOT NULL REFERENCES machine_states(state_id),to_state_id TEXT NOT NULL UNIQUE REFERENCES machine_states(state_id),accepted_frame_lf_sha256 TEXT NOT NULL CHECK(length(accepted_frame_lf_sha256)=64),matched_rule_id TEXT NOT NULL CHECK(matched_rule_id IN('D00','D10','D20','D30','D50','D60','D70','D80')),state_class TEXT NOT NULL CHECK(state_class IN('EMPTY','ABSTAIN_INCOMPLETE','PREFLIGHT_ONLY','COMMITMENT_RECORDED_MAY_HAVE_ENTERED','CONTAINMENT_REQUIRED','CONSERVATION_RECORDED','TERMINAL_RECORDED','REJECTED')),predicate_vector_sha256 TEXT NOT NULL CHECK(length(predicate_vector_sha256)=64),derived_post_hoc_source_set_sha256 TEXT NOT NULL CHECK(length(derived_post_hoc_source_set_sha256)=64),predecessor_derived_post_hoc_witness_merkle_root_sha256 TEXT NOT NULL CHECK(length(predecessor_derived_post_hoc_witness_merkle_root_sha256)=64),predecessor_derived_post_hoc_witness_leaf_count INTEGER NOT NULL CHECK(predecessor_derived_post_hoc_witness_leaf_count>=0),preconservation_merkle_committed TEXT NOT NULL CHECK(preconservation_merkle_committed IN('TRUE','FALSE','UNKNOWN')),preconservation_commitment_witness_id TEXT REFERENCES machine_witnesses(witness_id),authority_vector TEXT NOT NULL CHECK(authority_vector='00000000'),authoritative INTEGER NOT NULL CHECK(authoritative=0),may_feed_controller INTEGER NOT NULL CHECK(may_feed_controller=0),CHECK(from_state_id<>to_state_id),CHECK((preconservation_merkle_committed='TRUE' AND preconservation_commitment_witness_id IS NOT NULL) OR (preconservation_merkle_committed IN('FALSE','UNKNOWN') AND preconservation_commitment_witness_id IS NULL))) STRICT,WITHOUT ROWID;
CREATE TABLE machine_transition_bindings(transition_id TEXT PRIMARY KEY REFERENCES machine_transitions(transition_id),accepted_frame_node_id TEXT NOT NULL UNIQUE REFERENCES graph_nodes(node_id)) STRICT,WITHOUT ROWID;
CREATE TABLE machine_witnesses(witness_id TEXT PRIMARY KEY REFERENCES machine_nodes(machine_node_id),witness_kind TEXT NOT NULL CHECK(witness_kind IN('frame_adapter_coverage','targets','target_provenance','target_snapshots','commitments','signal_calls','conservations','terminal_outcomes','missing_evidence','conservation_set_commitments','conservation_set_memberships','conservation_set_membership_proof_nodes','conservation_set_conservation_states','conservation_set_obligation_mappings')),normalized_fact_sha256 TEXT NOT NULL UNIQUE CHECK(length(normalized_fact_sha256)=64),intrinsic_source_frame_lf_sha256 TEXT CHECK(intrinsic_source_frame_lf_sha256 IS NULL OR length(intrinsic_source_frame_lf_sha256)=64),visible_prefix_ordinal INTEGER NOT NULL CHECK(visible_prefix_ordinal>=0),authoritative INTEGER NOT NULL CHECK(authoritative=0),may_feed_controller INTEGER NOT NULL CHECK(may_feed_controller=0)) STRICT,WITHOUT ROWID;
CREATE TABLE machine_witness_bindings(witness_id TEXT PRIMARY KEY REFERENCES machine_witnesses(witness_id),source_database_role TEXT NOT NULL CHECK(source_database_role='EVIDENCE') REFERENCES input_databases(database_role),source_table TEXT NOT NULL,source_row_id TEXT NOT NULL,exact_row_sha256 TEXT NOT NULL CHECK(length(exact_row_sha256)=64),source_frame_node_id TEXT REFERENCES graph_nodes(node_id),UNIQUE(source_database_role,source_table,source_row_id)) STRICT,WITHOUT ROWID;
CREATE TABLE machine_transition_predicates(transition_id TEXT NOT NULL REFERENCES machine_transitions(transition_id),predicate_ordinal INTEGER NOT NULL CHECK(predicate_ordinal>=0),rule_ordinal INTEGER NOT NULL CHECK(rule_ordinal>=0),rule_id TEXT NOT NULL CHECK(rule_id IN('D00','D10','D20','D30','D50','D60','D70','D80')),clause_ordinal INTEGER NOT NULL CHECK(clause_ordinal>=0),predicate_clause TEXT NOT NULL CHECK(predicate_clause IN('input_set_admitted=false','input_set_admitted=true','preflight_snapshot_count>0','commitment_count=0','commitment_count>signal_result_count','entered_signal_without_complete_conservation=true','actuation_obligation_count>0','exact_preconservation_obligation_set_commitment=true','all_committed_obligations_conserved=true','terminal_count=0','exact_terminal_count=1','preactuation_rejection_terminal_count=1','entered_signal_count=0')),normalized_lhs TEXT NOT NULL CHECK(normalized_lhs IN('input_set_admitted','preflight_snapshot_count','commitment_count','signal_result_count','entered_signal_without_complete_conservation','actuation_obligation_count','exact_preconservation_obligation_set_commitment','all_committed_obligations_conserved','terminal_count','exact_terminal_count','preactuation_rejection_terminal_count','entered_signal_count')),normalized_operator TEXT NOT NULL CHECK(normalized_operator IN('=','>')),normalized_rhs TEXT NOT NULL CHECK(normalized_rhs IN('false','true','0','1','signal_result_count')),actual_scalar TEXT NOT NULL,normalized_state TEXT NOT NULL CHECK(normalized_state IN('TRUE','FALSE','UNKNOWN')),source_count INTEGER NOT NULL CHECK(source_count>=0),source_set_sha256 TEXT NOT NULL CHECK(length(source_set_sha256)=64),predicate_sha256 TEXT NOT NULL CHECK(length(predicate_sha256)=64),PRIMARY KEY(transition_id,predicate_ordinal),UNIQUE(transition_id,rule_ordinal,clause_ordinal)) STRICT,WITHOUT ROWID;
CREATE TABLE machine_merkle_leaves(state_id TEXT NOT NULL REFERENCES machine_states(state_id),leaf_ordinal INTEGER NOT NULL CHECK(leaf_ordinal>=0),witness_id TEXT NOT NULL REFERENCES machine_witnesses(witness_id),normalized_leaf_sha256 TEXT NOT NULL CHECK(length(normalized_leaf_sha256)=64),PRIMARY KEY(state_id,leaf_ordinal),UNIQUE(state_id,witness_id)) STRICT,WITHOUT ROWID;
CREATE TABLE machine_overlay_edges(overlay_edge_id TEXT PRIMARY KEY CHECK(length(overlay_edge_id)=64),from_node_id TEXT NOT NULL REFERENCES machine_nodes(machine_node_id),to_node_id TEXT NOT NULL REFERENCES machine_nodes(machine_node_id),edge_role TEXT NOT NULL CHECK(edge_role IN('PREDECESSOR','SUCCESSOR','SUPPORTS')),authoritative INTEGER NOT NULL CHECK(authoritative=0),may_feed_controller INTEGER NOT NULL CHECK(may_feed_controller=0),UNIQUE(from_node_id,to_node_id,edge_role)) STRICT,WITHOUT ROWID;
CREATE TABLE graph_seal(singleton INTEGER PRIMARY KEY CHECK(singleton=1),projection_id TEXT NOT NULL CHECK(length(projection_id)=64),evidence_database_sha256 TEXT NOT NULL CHECK(length(evidence_database_sha256)=64),metrics_database_sha256 TEXT NOT NULL CHECK(length(metrics_database_sha256)=64),ddl_sha256 TEXT NOT NULL CHECK(length(ddl_sha256)=64),adapter_sha256 TEXT NOT NULL CHECK(length(adapter_sha256)=64),lattice_sha256 TEXT NOT NULL CHECK(length(lattice_sha256)=64),graph_export_sha256 TEXT NOT NULL CHECK(length(graph_export_sha256)=64),node_count INTEGER NOT NULL CHECK(node_count>=0),edge_count INTEGER NOT NULL CHECK(edge_count>=0),state_evaluation_count INTEGER NOT NULL CHECK(state_evaluation_count>=0),authority_vector TEXT NOT NULL CHECK(authority_vector='00000000'),authoritative INTEGER NOT NULL CHECK(authoritative=0),may_feed_controller INTEGER NOT NULL CHECK(may_feed_controller=0)) STRICT;
CREATE VIEW presentation_authority_boundary AS SELECT authority_vector,authoritative,may_feed_controller,prose_may_supply_fact,unavailable_behavior FROM projection_policy WHERE singleton=1;
CREATE VIEW ui_graph_nodes AS SELECT node_id,node_kind,canonical_key,display_label,source_database_role,source_row_id FROM graph_nodes WHERE authoritative=0 ORDER BY node_id;
CREATE VIEW ui_graph_edges AS SELECT edge_id,from_node_id,predicate,to_node_id,source_database_role,source_row_id,source_pointer,evidence_grade FROM graph_edges WHERE authoritative=0 AND may_feed_controller=0 ORDER BY edge_id;
CREATE VIEW ui_state_machine_states AS SELECT s.state_id,s.prefix_ordinal,s.predecessor_state_id,s.ancestry_sha256,b.high_water_frame_node_id,s.high_water_frame_lf_sha256,s.matched_rule_id,s.predicate_vector_sha256,s.state_class,s.derived_post_hoc_witness_merkle_root_sha256,s.derived_post_hoc_witness_leaf_count,s.merkle_algorithm,s.merkle_domain_tag,s.merkle_leaf_ordering,s.merkle_duplicate_policy,s.merkle_odd_leaf_rule FROM machine_states s JOIN machine_state_bindings b ON b.state_id=s.state_id WHERE s.authoritative=0 AND s.may_feed_controller=0 ORDER BY s.prefix_ordinal;
CREATE VIEW ui_state_machine_transitions AS SELECT t.transition_id,t.from_state_id,t.to_state_id,b.accepted_frame_node_id,t.accepted_frame_lf_sha256,t.matched_rule_id,t.state_class,t.predicate_vector_sha256,t.derived_post_hoc_source_set_sha256,t.predecessor_derived_post_hoc_witness_merkle_root_sha256,t.predecessor_derived_post_hoc_witness_leaf_count,t.preconservation_merkle_committed,t.preconservation_commitment_witness_id FROM machine_transitions t JOIN machine_transition_bindings b ON b.transition_id=t.transition_id WHERE t.authoritative=0 AND t.may_feed_controller=0 ORDER BY t.accepted_frame_lf_sha256,t.transition_id;
CREATE VIEW ui_state_machine_witnesses AS SELECT w.witness_id,w.witness_kind,b.source_table,b.source_row_id,b.exact_row_sha256,w.normalized_fact_sha256,w.intrinsic_source_frame_lf_sha256,b.source_frame_node_id,w.visible_prefix_ordinal FROM machine_witnesses w JOIN machine_witness_bindings b ON b.witness_id=w.witness_id WHERE w.authoritative=0 AND w.may_feed_controller=0 ORDER BY b.source_table,b.source_row_id;
CREATE TRIGGER projection_policy_no_update BEFORE UPDATE ON projection_policy BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER projection_policy_no_delete BEFORE DELETE ON projection_policy BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER projection_policy_no_insert_after_seal BEFORE INSERT ON projection_policy WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER input_databases_no_update BEFORE UPDATE ON input_databases BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER input_databases_no_delete BEFORE DELETE ON input_databases BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER input_databases_no_insert_after_seal BEFORE INSERT ON input_databases WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER graph_nodes_no_update BEFORE UPDATE ON graph_nodes BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER graph_nodes_no_delete BEFORE DELETE ON graph_nodes BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER graph_nodes_no_insert_after_seal BEFORE INSERT ON graph_nodes WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER graph_edges_no_update BEFORE UPDATE ON graph_edges BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER graph_edges_no_delete BEFORE DELETE ON graph_edges BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER graph_edges_no_insert_after_seal BEFORE INSERT ON graph_edges WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER state_evaluations_no_update BEFORE UPDATE ON state_evaluations BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER state_evaluations_no_delete BEFORE DELETE ON state_evaluations BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER state_evaluations_no_insert_after_seal BEFORE INSERT ON state_evaluations WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER state_inputs_no_update BEFORE UPDATE ON state_inputs BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER state_inputs_no_delete BEFORE DELETE ON state_inputs BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER state_inputs_no_insert_after_seal BEFORE INSERT ON state_inputs WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER machine_nodes_no_update BEFORE UPDATE ON machine_nodes BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_nodes_no_delete BEFORE DELETE ON machine_nodes BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_nodes_no_insert_after_seal BEFORE INSERT ON machine_nodes WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER machine_states_no_update BEFORE UPDATE ON machine_states BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_states_no_delete BEFORE DELETE ON machine_states BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_states_no_insert_after_seal BEFORE INSERT ON machine_states WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER machine_states_subtype_and_ancestry BEFORE INSERT ON machine_states WHEN (SELECT machine_kind FROM machine_nodes WHERE machine_node_id=NEW.state_id)<>'STATE' OR (NEW.predecessor_state_id IS NOT NULL AND (SELECT prefix_ordinal FROM machine_states WHERE state_id=NEW.predecessor_state_id)+1<>NEW.prefix_ordinal) BEGIN SELECT RAISE(ABORT,'invalid-state-subtype-or-ancestry'); END;
CREATE TRIGGER machine_states_rule_class_join BEFORE INSERT ON machine_states WHEN (NEW.prefix_ordinal>=0 AND NEW.matched_rule_id='D00') OR NEW.state_class<>CASE NEW.matched_rule_id WHEN 'D00' THEN 'EMPTY' WHEN 'D10' THEN 'PREFLIGHT_ONLY' WHEN 'D20' THEN 'COMMITMENT_RECORDED_MAY_HAVE_ENTERED' WHEN 'D30' THEN 'CONTAINMENT_REQUIRED' WHEN 'D50' THEN 'CONSERVATION_RECORDED' WHEN 'D60' THEN 'TERMINAL_RECORDED' WHEN 'D70' THEN 'REJECTED' WHEN 'D80' THEN 'ABSTAIN_INCOMPLETE' END BEGIN SELECT RAISE(ABORT,'invalid-state-rule-class-join'); END;
CREATE TRIGGER machine_state_bindings_no_update BEFORE UPDATE ON machine_state_bindings BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_state_bindings_no_delete BEFORE DELETE ON machine_state_bindings BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_state_bindings_no_insert_after_seal BEFORE INSERT ON machine_state_bindings WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER machine_state_bindings_exact BEFORE INSERT ON machine_state_bindings WHEN (SELECT node_kind FROM graph_nodes WHERE node_id=NEW.invocation_node_id)<>'INVOCATION' OR (((SELECT prefix_ordinal FROM machine_states WHERE state_id=NEW.state_id)=-1)<>(NEW.high_water_frame_node_id IS NULL)) OR (NEW.high_water_frame_node_id IS NOT NULL AND (SELECT node_kind FROM graph_nodes WHERE node_id=NEW.high_water_frame_node_id)<>'FRAME') OR ((SELECT predecessor_state_id FROM machine_states WHERE state_id=NEW.state_id) IS NOT NULL AND (SELECT invocation_node_id FROM machine_state_bindings WHERE state_id=(SELECT predecessor_state_id FROM machine_states WHERE state_id=NEW.state_id))<>NEW.invocation_node_id) BEGIN SELECT RAISE(ABORT,'invalid-state-binding'); END;
CREATE TRIGGER machine_transitions_no_update BEFORE UPDATE ON machine_transitions BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_transitions_no_delete BEFORE DELETE ON machine_transitions BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_transitions_no_insert_after_seal BEFORE INSERT ON machine_transitions WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER machine_transitions_exact_join BEFORE INSERT ON machine_transitions WHEN (SELECT machine_kind FROM machine_nodes WHERE machine_node_id=NEW.transition_id)<>'TRANSITION' OR (SELECT machine_kind FROM machine_nodes WHERE machine_node_id=NEW.from_state_id)<>'STATE' OR (SELECT machine_kind FROM machine_nodes WHERE machine_node_id=NEW.to_state_id)<>'STATE' OR (SELECT predecessor_state_id FROM machine_states WHERE state_id=NEW.to_state_id)<>NEW.from_state_id OR (SELECT high_water_frame_lf_sha256 FROM machine_states WHERE state_id=NEW.to_state_id)<>NEW.accepted_frame_lf_sha256 OR (SELECT matched_rule_id FROM machine_states WHERE state_id=NEW.to_state_id)<>NEW.matched_rule_id OR (SELECT state_class FROM machine_states WHERE state_id=NEW.to_state_id)<>NEW.state_class OR (SELECT predicate_vector_sha256 FROM machine_states WHERE state_id=NEW.to_state_id)<>NEW.predicate_vector_sha256 OR (SELECT derived_post_hoc_witness_merkle_root_sha256 FROM machine_states WHERE state_id=NEW.from_state_id)<>NEW.predecessor_derived_post_hoc_witness_merkle_root_sha256 OR (SELECT derived_post_hoc_witness_leaf_count FROM machine_states WHERE state_id=NEW.from_state_id)<>NEW.predecessor_derived_post_hoc_witness_leaf_count OR (NEW.preconservation_merkle_committed='TRUE' AND ((SELECT witness_kind FROM machine_witnesses WHERE witness_id=NEW.preconservation_commitment_witness_id)<>'conservation_set_commitments' OR (SELECT visible_prefix_ordinal FROM machine_witnesses WHERE witness_id=NEW.preconservation_commitment_witness_id)>(SELECT prefix_ordinal FROM machine_states WHERE state_id=NEW.from_state_id))) BEGIN SELECT RAISE(ABORT,'invalid-transition-exact-join'); END;
CREATE TRIGGER machine_transitions_rule_class_join BEFORE INSERT ON machine_transitions WHEN NEW.matched_rule_id='D00' OR NEW.state_class<>CASE NEW.matched_rule_id WHEN 'D10' THEN 'PREFLIGHT_ONLY' WHEN 'D20' THEN 'COMMITMENT_RECORDED_MAY_HAVE_ENTERED' WHEN 'D30' THEN 'CONTAINMENT_REQUIRED' WHEN 'D50' THEN 'CONSERVATION_RECORDED' WHEN 'D60' THEN 'TERMINAL_RECORDED' WHEN 'D70' THEN 'REJECTED' WHEN 'D80' THEN 'ABSTAIN_INCOMPLETE' END BEGIN SELECT RAISE(ABORT,'invalid-transition-rule-class-join'); END;
CREATE TRIGGER machine_transition_bindings_no_update BEFORE UPDATE ON machine_transition_bindings BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_transition_bindings_no_delete BEFORE DELETE ON machine_transition_bindings BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_transition_bindings_no_insert_after_seal BEFORE INSERT ON machine_transition_bindings WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER machine_transition_bindings_exact BEFORE INSERT ON machine_transition_bindings WHEN (SELECT node_kind FROM graph_nodes WHERE node_id=NEW.accepted_frame_node_id)<>'FRAME' OR (SELECT high_water_frame_node_id FROM machine_state_bindings WHERE state_id=(SELECT to_state_id FROM machine_transitions WHERE transition_id=NEW.transition_id))<>NEW.accepted_frame_node_id BEGIN SELECT RAISE(ABORT,'invalid-transition-binding'); END;
CREATE TRIGGER machine_witnesses_no_update BEFORE UPDATE ON machine_witnesses BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_witnesses_no_delete BEFORE DELETE ON machine_witnesses BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_witnesses_no_insert_after_seal BEFORE INSERT ON machine_witnesses WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER machine_witnesses_subtype BEFORE INSERT ON machine_witnesses WHEN (SELECT machine_kind FROM machine_nodes WHERE machine_node_id=NEW.witness_id)<>'WITNESS' BEGIN SELECT RAISE(ABORT,'invalid-witness-subtype'); END;
CREATE TRIGGER machine_witness_bindings_no_update BEFORE UPDATE ON machine_witness_bindings BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_witness_bindings_no_delete BEFORE DELETE ON machine_witness_bindings BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_witness_bindings_no_insert_after_seal BEFORE INSERT ON machine_witness_bindings WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER machine_witness_bindings_exact BEFORE INSERT ON machine_witness_bindings WHEN (SELECT witness_kind FROM machine_witnesses WHERE witness_id=NEW.witness_id)<>NEW.source_table OR (NEW.source_frame_node_id IS NOT NULL AND (SELECT node_kind FROM graph_nodes WHERE node_id=NEW.source_frame_node_id)<>'FRAME') BEGIN SELECT RAISE(ABORT,'invalid-witness-binding'); END;
CREATE TRIGGER machine_transition_predicates_no_update BEFORE UPDATE ON machine_transition_predicates BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_transition_predicates_no_delete BEFORE DELETE ON machine_transition_predicates BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_transition_predicates_no_insert_after_seal BEFORE INSERT ON machine_transition_predicates WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER machine_transition_predicates_exact_join BEFORE INSERT ON machine_transition_predicates WHEN NEW.normalized_lhs||'|'||NEW.normalized_operator||'|'||NEW.normalized_rhs<>CASE NEW.predicate_clause WHEN 'input_set_admitted=false' THEN 'input_set_admitted|=|false' WHEN 'input_set_admitted=true' THEN 'input_set_admitted|=|true' WHEN 'preflight_snapshot_count>0' THEN 'preflight_snapshot_count|>|0' WHEN 'commitment_count=0' THEN 'commitment_count|=|0' WHEN 'commitment_count>signal_result_count' THEN 'commitment_count|>|signal_result_count' WHEN 'entered_signal_without_complete_conservation=true' THEN 'entered_signal_without_complete_conservation|=|true' WHEN 'actuation_obligation_count>0' THEN 'actuation_obligation_count|>|0' WHEN 'exact_preconservation_obligation_set_commitment=true' THEN 'exact_preconservation_obligation_set_commitment|=|true' WHEN 'all_committed_obligations_conserved=true' THEN 'all_committed_obligations_conserved|=|true' WHEN 'terminal_count=0' THEN 'terminal_count|=|0' WHEN 'exact_terminal_count=1' THEN 'exact_terminal_count|=|1' WHEN 'preactuation_rejection_terminal_count=1' THEN 'preactuation_rejection_terminal_count|=|1' WHEN 'entered_signal_count=0' THEN 'entered_signal_count|=|0' END OR (NEW.predicate_ordinal IN(5,9) AND EXISTS(SELECT 1 FROM machine_transitions t WHERE t.transition_id=NEW.transition_id AND (NEW.normalized_state<>t.preconservation_merkle_committed OR NEW.actual_scalar<>CASE t.preconservation_merkle_committed WHEN 'TRUE' THEN 'true' WHEN 'FALSE' THEN 'false' ELSE 'UNKNOWN' END))) BEGIN SELECT RAISE(ABORT,'invalid-machine-predicate-join'); END;
CREATE TRIGGER machine_transition_predicates_duplicate_semantics BEFORE INSERT ON machine_transition_predicates WHEN EXISTS(SELECT 1 FROM machine_transition_predicates p WHERE p.transition_id=NEW.transition_id AND p.predicate_clause=NEW.predicate_clause AND (p.actual_scalar<>NEW.actual_scalar OR p.normalized_state<>NEW.normalized_state OR p.source_count<>NEW.source_count OR p.source_set_sha256<>NEW.source_set_sha256)) BEGIN SELECT RAISE(ABORT,'duplicate-machine-predicate-semantic-mismatch'); END;
CREATE TRIGGER machine_merkle_leaves_no_update BEFORE UPDATE ON machine_merkle_leaves BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_merkle_leaves_no_delete BEFORE DELETE ON machine_merkle_leaves BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_merkle_leaves_no_insert_after_seal BEFORE INSERT ON machine_merkle_leaves WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER machine_merkle_leaves_prefix BEFORE INSERT ON machine_merkle_leaves WHEN (SELECT visible_prefix_ordinal FROM machine_witnesses WHERE witness_id=NEW.witness_id)>(SELECT prefix_ordinal FROM machine_states WHERE state_id=NEW.state_id) BEGIN SELECT RAISE(ABORT,'future-witness-in-prefix-merkle'); END;
CREATE TRIGGER machine_overlay_edges_no_update BEFORE UPDATE ON machine_overlay_edges BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_overlay_edges_no_delete BEFORE DELETE ON machine_overlay_edges BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER machine_overlay_edges_no_insert_after_seal BEFORE INSERT ON machine_overlay_edges WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER machine_overlay_edges_bipartite BEFORE INSERT ON machine_overlay_edges WHEN (SELECT partition_kind FROM machine_nodes WHERE machine_node_id=NEW.from_node_id)=(SELECT partition_kind FROM machine_nodes WHERE machine_node_id=NEW.to_node_id) OR (NEW.edge_role='PREDECESSOR' AND ((SELECT machine_kind FROM machine_nodes WHERE machine_node_id=NEW.from_node_id)<>'STATE' OR (SELECT machine_kind FROM machine_nodes WHERE machine_node_id=NEW.to_node_id)<>'TRANSITION' OR (SELECT from_state_id FROM machine_transitions WHERE transition_id=NEW.to_node_id)<>NEW.from_node_id)) OR (NEW.edge_role='SUCCESSOR' AND ((SELECT machine_kind FROM machine_nodes WHERE machine_node_id=NEW.from_node_id)<>'TRANSITION' OR (SELECT machine_kind FROM machine_nodes WHERE machine_node_id=NEW.to_node_id)<>'STATE' OR (SELECT to_state_id FROM machine_transitions WHERE transition_id=NEW.from_node_id)<>NEW.to_node_id)) OR (NEW.edge_role='SUPPORTS' AND ((SELECT machine_kind FROM machine_nodes WHERE machine_node_id=NEW.from_node_id)<>'WITNESS' OR (SELECT machine_kind FROM machine_nodes WHERE machine_node_id=NEW.to_node_id)<>'TRANSITION' OR (SELECT visible_prefix_ordinal FROM machine_witnesses WHERE witness_id=NEW.from_node_id)>(SELECT prefix_ordinal FROM machine_states WHERE state_id=(SELECT to_state_id FROM machine_transitions WHERE transition_id=NEW.to_node_id)))) BEGIN SELECT RAISE(ABORT,'non-bipartite-overlay'); END;
CREATE TRIGGER graph_seal_no_update BEFORE UPDATE ON graph_seal BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER graph_seal_no_delete BEFORE DELETE ON graph_seal BEGIN SELECT RAISE(ABORT,'append-only'); END;
CREATE TRIGGER graph_seal_no_insert_after_seal BEFORE INSERT ON graph_seal WHEN EXISTS(SELECT 1 FROM graph_seal WHERE singleton=1) BEGIN SELECT RAISE(ABORT,'sealed'); END;
CREATE TRIGGER graph_seal_machine_completeness BEFORE INSERT ON graph_seal WHEN (SELECT count(*) FROM machine_states WHERE prefix_ordinal=-1)<>1 OR (SELECT count(*) FROM machine_state_bindings)<>(SELECT count(*) FROM machine_states) OR (SELECT count(*) FROM machine_transition_bindings)<>(SELECT count(*) FROM machine_transitions) OR (SELECT count(*) FROM machine_witness_bindings)<>(SELECT count(*) FROM machine_witnesses) OR (SELECT count(*) FROM machine_transitions)<>(SELECT count(*) FROM machine_states WHERE prefix_ordinal>=0) OR EXISTS(SELECT 1 FROM machine_transitions t WHERE (SELECT count(*) FROM machine_overlay_edges e WHERE e.edge_role='PREDECESSOR' AND e.from_node_id=t.from_state_id AND e.to_node_id=t.transition_id)<>1 OR (SELECT count(*) FROM machine_overlay_edges e WHERE e.edge_role='SUCCESSOR' AND e.from_node_id=t.transition_id AND e.to_node_id=t.to_state_id)<>1) OR EXISTS(SELECT 1 FROM machine_states s WHERE s.prefix_ordinal>=0 AND (SELECT count(*) FROM machine_transitions t WHERE t.to_state_id=s.state_id)<>1) OR EXISTS(SELECT 1 FROM machine_states s WHERE (s.prefix_ordinal<(SELECT max(prefix_ordinal) FROM machine_states) AND (SELECT count(*) FROM machine_transitions t WHERE t.from_state_id=s.state_id)<>1) OR (s.prefix_ordinal=(SELECT max(prefix_ordinal) FROM machine_states) AND (SELECT count(*) FROM machine_transitions t WHERE t.from_state_id=s.state_id)<>0)) OR EXISTS(SELECT 1 FROM machine_overlay_edges e JOIN machine_transitions t ON t.transition_id=e.to_node_id WHERE e.edge_role='SUPPORTS' AND NOT EXISTS(SELECT 1 FROM machine_merkle_leaves l WHERE l.state_id=t.to_state_id AND l.witness_id=e.from_node_id)) OR EXISTS(SELECT 1 FROM machine_merkle_leaves l JOIN machine_transitions t ON t.to_state_id=l.state_id WHERE NOT EXISTS(SELECT 1 FROM machine_overlay_edges e WHERE e.edge_role='SUPPORTS' AND e.from_node_id=l.witness_id AND e.to_node_id=t.transition_id)) OR EXISTS(SELECT 1 FROM machine_states s JOIN machine_witnesses w ON w.visible_prefix_ordinal<=s.prefix_ordinal WHERE NOT EXISTS(SELECT 1 FROM machine_merkle_leaves l WHERE l.state_id=s.state_id AND l.witness_id=w.witness_id)) OR EXISTS(SELECT 1 FROM machine_states s WHERE (SELECT count(*) FROM machine_merkle_leaves l WHERE l.state_id=s.state_id)<>s.derived_post_hoc_witness_leaf_count OR (SELECT count(*) FROM machine_merkle_leaves l WHERE l.state_id=s.state_id)<>(SELECT count(*) FROM machine_witnesses w WHERE w.visible_prefix_ordinal<=s.prefix_ordinal) OR (s.derived_post_hoc_witness_leaf_count>0 AND ((SELECT min(leaf_ordinal) FROM machine_merkle_leaves l WHERE l.state_id=s.state_id)<>0 OR (SELECT max(leaf_ordinal) FROM machine_merkle_leaves l WHERE l.state_id=s.state_id)<>s.derived_post_hoc_witness_leaf_count-1))) OR EXISTS(SELECT 1 FROM machine_transitions t WHERE (SELECT count(*) FROM machine_transition_predicates p WHERE p.transition_id=t.transition_id)<>18 OR (SELECT min(predicate_ordinal) FROM machine_transition_predicates p WHERE p.transition_id=t.transition_id)<>0 OR (SELECT max(predicate_ordinal) FROM machine_transition_predicates p WHERE p.transition_id=t.transition_id)<>17 OR NOT EXISTS(SELECT 1 FROM machine_transition_predicates p WHERE p.transition_id=t.transition_id AND p.rule_id=t.matched_rule_id GROUP BY p.rule_id HAVING min(p.normalized_state='TRUE')=1) OR EXISTS(SELECT 1 FROM machine_transition_predicates earlier WHERE earlier.transition_id=t.transition_id AND earlier.rule_ordinal<(SELECT min(rule_ordinal) FROM machine_transition_predicates matched WHERE matched.transition_id=t.transition_id AND matched.rule_id=t.matched_rule_id) GROUP BY earlier.rule_ordinal HAVING min(earlier.normalized_state='TRUE')=1)) BEGIN SELECT RAISE(ABORT,'incomplete-machine-seal'); END;
CREATE TRIGGER graph_seal_machine_predicate_inventory BEFORE INSERT ON graph_seal WHEN EXISTS(SELECT 1 FROM machine_transition_predicates p WHERE CAST(p.rule_ordinal AS TEXT)||'|'||p.rule_id||'|'||CAST(p.clause_ordinal AS TEXT)||'|'||p.predicate_clause||'|'||p.normalized_lhs||'|'||p.normalized_operator||'|'||p.normalized_rhs<>CASE p.predicate_ordinal WHEN 0 THEN '0|D00|0|input_set_admitted=false|input_set_admitted|=|false' WHEN 1 THEN '1|D30|0|entered_signal_without_complete_conservation=true|entered_signal_without_complete_conservation|=|true' WHEN 2 THEN '2|D70|0|preactuation_rejection_terminal_count=1|preactuation_rejection_terminal_count|=|1' WHEN 3 THEN '2|D70|1|entered_signal_count=0|entered_signal_count|=|0' WHEN 4 THEN '3|D60|0|actuation_obligation_count>0|actuation_obligation_count|>|0' WHEN 5 THEN '3|D60|1|exact_preconservation_obligation_set_commitment=true|exact_preconservation_obligation_set_commitment|=|true' WHEN 6 THEN '3|D60|2|all_committed_obligations_conserved=true|all_committed_obligations_conserved|=|true' WHEN 7 THEN '3|D60|3|exact_terminal_count=1|exact_terminal_count|=|1' WHEN 8 THEN '4|D50|0|actuation_obligation_count>0|actuation_obligation_count|>|0' WHEN 9 THEN '4|D50|1|exact_preconservation_obligation_set_commitment=true|exact_preconservation_obligation_set_commitment|=|true' WHEN 10 THEN '4|D50|2|all_committed_obligations_conserved=true|all_committed_obligations_conserved|=|true' WHEN 11 THEN '4|D50|3|terminal_count=0|terminal_count|=|0' WHEN 12 THEN '5|D20|0|commitment_count>signal_result_count|commitment_count|>|signal_result_count' WHEN 13 THEN '6|D10|0|input_set_admitted=true|input_set_admitted|=|true' WHEN 14 THEN '6|D10|1|preflight_snapshot_count>0|preflight_snapshot_count|>|0' WHEN 15 THEN '6|D10|2|commitment_count=0|commitment_count|=|0' WHEN 16 THEN '6|D10|3|terminal_count=0|terminal_count|=|0' WHEN 17 THEN '7|D80|0|input_set_admitted=true|input_set_admitted|=|true' ELSE 'INVALID' END) BEGIN SELECT RAISE(ABORT,'invalid-machine-predicate-inventory'); END;
CREATE TRIGGER graph_seal_machine_temporal_commitment_join BEFORE INSERT ON graph_seal WHEN EXISTS(SELECT 1 FROM machine_states s WHERE (s.prefix_ordinal>=0 AND s.matched_rule_id='D00') OR s.state_class<>CASE s.matched_rule_id WHEN 'D00' THEN 'EMPTY' WHEN 'D10' THEN 'PREFLIGHT_ONLY' WHEN 'D20' THEN 'COMMITMENT_RECORDED_MAY_HAVE_ENTERED' WHEN 'D30' THEN 'CONTAINMENT_REQUIRED' WHEN 'D50' THEN 'CONSERVATION_RECORDED' WHEN 'D60' THEN 'TERMINAL_RECORDED' WHEN 'D70' THEN 'REJECTED' WHEN 'D80' THEN 'ABSTAIN_INCOMPLETE' END) OR EXISTS(SELECT 1 FROM machine_transitions t WHERE t.matched_rule_id='D00' OR t.state_class<>CASE t.matched_rule_id WHEN 'D10' THEN 'PREFLIGHT_ONLY' WHEN 'D20' THEN 'COMMITMENT_RECORDED_MAY_HAVE_ENTERED' WHEN 'D30' THEN 'CONTAINMENT_REQUIRED' WHEN 'D50' THEN 'CONSERVATION_RECORDED' WHEN 'D60' THEN 'TERMINAL_RECORDED' WHEN 'D70' THEN 'REJECTED' WHEN 'D80' THEN 'ABSTAIN_INCOMPLETE' END OR (SELECT count(*) FROM machine_transition_predicates p WHERE p.transition_id=t.transition_id AND p.predicate_ordinal IN(5,9) AND p.normalized_state=t.preconservation_merkle_committed AND p.actual_scalar=CASE t.preconservation_merkle_committed WHEN 'TRUE' THEN 'true' WHEN 'FALSE' THEN 'false' ELSE 'UNKNOWN' END)<>2) BEGIN SELECT RAISE(ABORT,'invalid-machine-temporal-commitment-join'); END;
CREATE TRIGGER graph_seal_machine_duplicate_predicate_semantics BEFORE INSERT ON graph_seal WHEN EXISTS(SELECT 1 FROM machine_transition_predicates a JOIN machine_transition_predicates b ON b.transition_id=a.transition_id AND b.predicate_clause=a.predicate_clause AND b.predicate_ordinal>a.predicate_ordinal WHERE a.actual_scalar<>b.actual_scalar OR a.normalized_state<>b.normalized_state OR a.source_count<>b.source_count OR a.source_set_sha256<>b.source_set_sha256) BEGIN SELECT RAISE(ABORT,'duplicate-machine-predicate-semantic-mismatch'); END;
CREATE TRIGGER graph_seal_machine_frame_inventory BEFORE INSERT ON graph_seal WHEN (SELECT count(*) FROM graph_nodes WHERE node_kind='FRAME')<1 OR (SELECT count(*) FROM machine_transition_bindings)<>(SELECT count(*) FROM graph_nodes WHERE node_kind='FRAME') OR EXISTS(SELECT 1 FROM graph_nodes f WHERE f.node_kind='FRAME' AND NOT EXISTS(SELECT 1 FROM machine_transition_bindings b WHERE b.accepted_frame_node_id=f.node_id)) OR (SELECT count(*) FROM machine_nodes)<>(SELECT count(*) FROM machine_states)+(SELECT count(*) FROM machine_witnesses)+(SELECT count(*) FROM machine_transitions) OR EXISTS(SELECT 1 FROM machine_witnesses w WHERE w.visible_prefix_ordinal>(SELECT max(prefix_ordinal) FROM machine_states)) BEGIN SELECT RAISE(ABORT,'invalid-machine-frame-inventory'); END;
